//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error represents a transient fault.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Creates a retry configuration.
    pub const fn new(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> Self {
        Self {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    /// Returns the delay for a retry, with exponential growth capped at the maximum.
    pub(crate) fn delay_for_retry(&self, retry_number: u32) -> u64 {
        let exponent = retry_number.saturating_sub(1);
        let multiplier = 1u64
            .checked_shl(exponent)
            .unwrap_or(u64::MAX);
        self.base_delay_ms
            .saturating_mul(multiplier)
            .min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delays_grow_exponentially_and_saturate() {
        let config = RetryConfig::new(5, 10, 25);
        assert_eq!(config.delay_for_retry(1), 10);
        assert_eq!(config.delay_for_retry(2), 20);
        assert_eq!(config.delay_for_retry(3), 25);
        assert_eq!(config.delay_for_retry(4), 25);
    }

    #[test]
    fn delay_calculation_reaches_the_cap_after_shift_overflow() {
        let config = RetryConfig::new(100, 1, u64::MAX);
        assert_eq!(config.delay_for_retry(65), u64::MAX);
    }

    #[test]
    fn delay_calculation_handles_arithmetic_overflow() {
        let config = RetryConfig::new(2, u64::MAX, u64::MAX);
        assert_eq!(config.delay_for_retry(2), u64::MAX);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    // A zero-attempt configuration cannot make a call; honor the documented
    // minimum without introducing a new public error variant.
    let max_attempts = config.max_attempts.max(1);
    let mut attempts = 0;

    loop {
        attempts += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() => return Err(error),
            Err(error) if attempts >= max_attempts => return Err(error),
            Err(_) => {
                let retry_number = attempts;
                sleeper.sleep_ms(config.delay_for_retry(retry_number));
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::cell::Cell;

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig::new(max_attempts, base_delay_ms, max_delay_ms)
    }

    #[test]
    fn retries_transient_errors_until_success() {
        let calls = Cell::new(0);
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config(4, 10, 100), &mut sleeper, || {
            calls.set(calls.get() + 1);
            if calls.get() < 3 {
                Err(RetryError::Transient("temporary".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls.get(), 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn permanent_errors_return_without_retrying() {
        let calls = Cell::new(0);
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config(5, 10, 100), &mut sleeper, || {
            calls.set(calls.get() + 1);
            Err(RetryError::Permanent("invalid".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid".into())));
        assert_eq!(calls.get(), 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_first_call() {
        let calls = Cell::new(0);
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config(3, 1, 100), &mut sleeper, || {
            calls.set(calls.get() + 1);
            Err(RetryError::Transient("down".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("down".into())));
        assert_eq!(calls.get(), 3);
        assert_eq!(sleeper.sleeps, vec![1, 2]);
    }
}

use jobrunner::{run_job, RetryConfig, RetryError, FakeSleeper};

#[test]
fn public_api_retries_transient_failures_with_a_bounded_schedule() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(
        &RetryConfig::new(5, 10, 25),
        &mut sleeper,
        || {
            calls += 1;
            if calls < 5 {
                Err(RetryError::Transient("service unavailable".into()))
            } else {
                Ok(())
            }
        },
    );

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 5);
    assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
}

#[test]
fn public_api_does_not_retry_permanent_failures() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(
        &RetryConfig::new(5, 10, 25),
        &mut sleeper,
        || {
            calls += 1;
            Err(RetryError::Permanent("invalid job".into()))
        },
    );

    assert_eq!(result, Err(RetryError::Permanent("invalid job".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}
